// The integer half of base58: `b58encode_int` and `b58decode_int`.
//
// All arithmetic is done with BigInt so values are unbounded, matching Python
// ints. Values are carried as octet arrays / strings rather than any binary
// buffer type.

import { PyValueError } from '../pyerrors.mjs';
import { PyBytes } from '../pybytes.mjs';
import { strRepr } from '../pyrepr.mjs';
import { pyRstrip } from '../pystr.mjs';
import { BITCOIN_ALPHABET, BASE, buildDigitMap } from './alphabet.mjs';
import { encodeAscii } from './scrub.mjs';

/**
 * Python's `divmod` for integers: the quotient floors toward negative infinity
 * and the remainder takes the sign of the divisor. BigInt's own `/` truncates
 * and `%` follows the dividend, so both need correcting.
 */
function pyDivMod(a, b) {
  let quotient = a / b;
  let remainder = a % b;

  if (remainder !== 0n && remainder < 0n !== b < 0n) {
    quotient -= 1n;
    remainder += b;
  }

  return [quotient, remainder];
}

/**
 * `b58encode_int(i)` — encode an integer to a base58 byte string.
 *
 * Zero maps to the alphabet's first character ('1') because of the library's
 * `default_one` behaviour, not because of positional arithmetic.
 *
 * Note: the reference implementation loops on `while i:` using floored divmod,
 * so a negative input never converges — divmod(-1, 58) is (-1, 57) forever.
 * The port keeps the same arithmetic, and therefore the same non-termination,
 * rather than inventing behaviour the original does not have.
 *
 * @param {bigint} i
 * @returns {PyBytes}
 */
export function b58encodeInt(i, { defaultOne = true, alphabet = BITCOIN_ALPHABET } = {}) {
  if (i === 0n && defaultOne) {
    return PyBytes.fromLatin1(alphabet.slice(0, 1));
  }

  const digits = [];
  let value = i;

  while (value !== 0n) {
    const [quotient, index] = pyDivMod(value, BigInt(alphabet.length));
    digits.push(alphabet.charCodeAt(Number(index)));
    value = quotient;
  }

  digits.reverse();
  return new PyBytes(digits);
}

const DIGIT_MAP = buildDigitMap(BITCOIN_ALPHABET);

/**
 * `b58decode_int(v)` — decode a base58 string to an integer.
 *
 * The reference library right-strips the input first (the alphabet contains no
 * space, so trailing whitespace is considered padding), then encodes it as
 * ASCII, then folds the digits. Order matters: trailing whitespace is dropped
 * before the ASCII check, and leading or interior whitespace survives to be
 * reported as an invalid character.
 *
 * @param {string} v
 * @returns {bigint}
 */
export function b58decodeInt(v, { alphabet = BITCOIN_ALPHABET } = {}) {
  const stripped = alphabet.includes(' ') ? v : pyRstrip(v);
  const octets = encodeAscii(stripped);

  const base = BigInt(alphabet.length);
  let decimal = 0n;

  for (const octet of octets) {
    const digit = DIGIT_MAP.get(octet);
    if (digit === undefined) {
      // Python formats this with {!r}, so control characters arrive escaped
      // and a literal quote flips the surrounding quote style.
      const error = new PyValueError(`Invalid character ${strRepr(String.fromCharCode(octet))}`);
      error.pyFrames = ['File "base58/__init__.py", line 104, in b58decode_int'];
      throw error;
    }
    decimal = decimal * base + BigInt(digit);
  }

  return decimal;
}

export { BASE, BITCOIN_ALPHABET };
