// Port of base58's `scrub_input`: a str argument is encoded with the *ascii*
// codec before decoding, so any character above U+007F raises
// UnicodeEncodeError rather than being treated as an invalid base58 digit.

import { PyUnicodeEncodeError } from '../pyerrors.mjs';
import { escapeCodePoint } from '../pyrepr.mjs';
import { codePoints } from '../pystr.mjs';

/**
 * Encode a str to ASCII octets. On failure, reproduces CPython's message,
 * which reports the maximal run of consecutive non-encodable characters and
 * its code-point position(s).
 *
 * @returns {number[]} octet values
 */
export function encodeAscii(text) {
  const chars = codePoints(text);

  const start = chars.findIndex((ch) => ch.codePointAt(0) > 0x7f);
  if (start !== -1) {
    let end = start;
    while (end + 1 < chars.length && chars[end + 1].codePointAt(0) > 0x7f) end++;

    const run = chars.slice(start, end + 1);
    const escaped = run.map((ch) => escapeCodePoint(ch.codePointAt(0))).join('');
    const noun = run.length === 1 ? 'character' : 'characters';
    const where = run.length === 1 ? `position ${start}` : `position ${start}-${end}`;

    const error = new PyUnicodeEncodeError(
      `'ascii' codec can't encode ${noun} '${escaped}' in ${where}: ordinal not in range(128)`,
    );
    error.pyFrames = [
      'File "base58/__init__.py", line 94, in b58decode_int',
      'File "base58/__init__.py", line 30, in scrub_input',
    ];
    throw error;
  }

  return chars.map((ch) => ch.codePointAt(0));
}
