// Renders an uncaught Python exception the way CPython prints it to stderr, so
// the failure modes of the port look like the failure modes of the original.
//
// Two details of the reference build are reproduced here:
//
//  * CPython resolves source lines through linecache at traceback time, so the
//    offending statement and its caret line only appear when a file named
//    test14.py is readable from the working directory. Run the reference binary
//    from a directory without it and those two lines vanish.
//  * The caret span comes from column offsets baked into the compiled code
//    object, not from re-parsing the line, so it stays fixed at the
//    `base58.b58decode_int(args.c)` sub-expression.
//
// The frozen build also emits a PyInstaller bootloader line whose embedded
// process id changes every run; that is a launcher artifact rather than part of
// the Python program, so it is not reproduced. stdout stays empty either way and
// the exit status is 1 in both.

import { readFileSync } from 'node:fs';

const SOURCE_FILE = 'test14.py';
const TRACEBACK_INDENT = '    ';

/** Read one 1-indexed line of a source file, or null if unavailable. */
function lookupLine(fileName, lineNumber) {
  try {
    const lines = readFileSync(fileName, 'utf8').split('\n');
    return lines[lineNumber - 1] ?? null;
  } catch {
    return null;
  }
}

/** The `^^^^` line CPython draws under the failing sub-expression. */
function caretLine(source, colStart, colEnd) {
  const start = Math.min(colStart, source.length);
  const end = Math.min(colEnd, source.length);
  if (end <= start) return null;
  return ' '.repeat(start) + '^'.repeat(end - start);
}

/**
 * @param {{pyType: string, pyMessage: string, pyFrames?: string[]}} error
 * @param {{line: number, colStart: number, colEnd: number}} callSite
 */
export function formatTraceback(error, callSite) {
  let out = 'Traceback (most recent call last):\n';
  out += `  File "${SOURCE_FILE}", line ${callSite.line}, in <module>\n`;

  const raw = lookupLine(SOURCE_FILE, callSite.line);
  if (raw !== null) {
    const source = raw.trim();
    out += `${TRACEBACK_INDENT}${source}\n`;
    const carets = caretLine(source, callSite.colStart, callSite.colEnd);
    if (carets !== null) out += `${TRACEBACK_INDENT}${carets}\n`;
  }

  for (const frame of error.pyFrames ?? []) {
    out += `  ${frame}\n`;
  }

  out += `${error.pyType}: ${error.pyMessage}\n`;
  return out;
}

export function writeTraceback(error, callSite) {
  process.stderr.write(formatTraceback(error, callSite));
}
