// A minimal stand-in for Python's `bytes`, holding octet values in a plain
// array so the base58 routines can pass around and print byte strings while
// keeping Python's distinction between str and bytes visible in the output.

import { bytesRepr } from './pyrepr.mjs';

export class PyBytes {
  /** @param {number[]} octets values in 0..255 */
  constructor(octets) {
    this.octets = octets;
  }

  /** Build from a string whose code points are all <= 0xff. */
  static fromLatin1(text) {
    return new PyBytes([...text].map((ch) => ch.codePointAt(0)));
  }

  get length() {
    return this.octets.length;
  }

  /** repr(), which is also what print() emits for a bytes object. */
  toString() {
    return bytesRepr(this.octets);
  }
}
