// Python exception surface, reduced to the classes this program can actually
// raise. Each carries the fields the traceback formatter needs so the entry
// point can reproduce CPython's stderr shape.

export class PyError extends Error {
  constructor(pyType, pyMessage) {
    super(`${pyType}: ${pyMessage}`);
    this.pyType = pyType;
    this.pyMessage = pyMessage;
  }
}

export class PyValueError extends PyError {
  constructor(pyMessage) {
    super('ValueError', pyMessage);
  }
}

/**
 * Raised by the ASCII codec. Python renders the offending run as
 * `'ascii' codec can't encode character(s) '<escaped>' in position i[-j]:
 * ordinal not in range(128)`.
 */
export class PyUnicodeEncodeError extends PyError {
  constructor(pyMessage) {
    super('UnicodeEncodeError', pyMessage);
  }
}
