  const start = chars.findIndex((ch) => ch.codePointAt(0) > 0x7f);
  if (start !== -1) {
    let end = start;
    while (end + 1 < chars.length && chars[end + 1].codePointAt(0) > 0x7f) end++;

    const detail =
      start === end
        ? `character '${escapeCodePoint(chars[start].codePointAt(0))}' in position ${start}`
